import { expect, type Page } from "@playwright/test";

export const getLocators = (page: Page) => {
  const inspectorCanvas = page.getByTestId("inspector-canvas");
  const sidePanel = page.getByTestId("inspector-side-panel");
  const eventDetailsPanel = inspectorCanvas.or(sidePanel);

  return {
    inspectorCanvas,
    eventDetailsPanel,
    closeButton: page.getByTestId("event-details-close"),
    panelHeading: (title: string) => page.getByRole("heading", { name: title }),
    slotOrFlowName: page.getByTestId("event-slot-or-flow-name"),
    slotValue: page.getByTestId("event-slot-value"),
    actionEventInfo: page.getByTestId("action-event-info"),
    mcpToolArguments: page.getByTestId("event-mcp-tool-arguments"),
    mcpToolResult: page.getByTestId("event-mcp-tool-result"),
    errorAlert: eventDetailsPanel.getByRole("alert"),
    accordionTrigger: (title: string) => eventDetailsPanel.getByRole("button", { name: title }),
    accordionTitle: (title: string) => eventDetailsPanel.getByText(title, { exact: true }),
  };
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    close: async () => {
      await locators.closeButton.click();
    },
    expandAccordion: async (title: string) => {
      await locators.accordionTrigger(title).click();
    },
    collapseAccordion: async (title: string) => {
      await locators.accordionTrigger(title).click();
    },
    focusCloseButton: async () => {
      await locators.closeButton.focus();
    },
    pressEscape: async () => {
      await page.keyboard.press("Escape");
    },
    pressEnter: async () => {
      await page.keyboard.press("Enter");
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    panelIsVisible: async (title: string) => {
      await expect(
        locators.panelHeading(title),
        `Event details panel with title "${title}" should be visible`,
      ).toBeVisible();
    },
    panelIsHidden: async () => {
      await expect(
        locators.closeButton,
        "Event details close button should not be visible",
      ).toBeHidden();
    },
    slotOrFlowNameIsVisible: async (name: string) => {
      await expect(
        locators.slotOrFlowName,
        `Slot or flow name "${name}" should be visible`,
      ).toContainText(name);
    },
    slotValueIsVisible: async (value?: string) => {
      if (value === undefined) {
        await expect(locators.slotValue, "Slot value should be visible").toBeVisible();
        return;
      }
      await expect(locators.slotValue, `Slot value "${value}" should be visible`).toContainText(
        value,
      );
    },
    actionEventInfoIsVisible: async () => {
      await expect(locators.actionEventInfo, "Action event info should be visible").toBeVisible();
    },
    panelContainsText: async (text: string) => {
      await expect(
        locators.eventDetailsPanel,
        `Event details panel should contain text "${text}"`,
      ).toContainText(text);
    },
    accordionIsVisible: async (title: string) => {
      await expect(
        locators.accordionTitle(title),
        `Accordion item "${title}" should be visible`,
      ).toBeVisible();
    },
    mcpToolArgumentsVisible: async () => {
      await expect(
        locators.mcpToolArguments,
        "MCP tool arguments should be visible in event details",
      ).toBeVisible();
    },
    mcpToolResultVisible: async () => {
      await expect(
        locators.mcpToolResult,
        "MCP tool result should be visible in event details",
      ).toBeVisible();
    },
    errorAlertIsVisible: async () => {
      await expect(
        locators.errorAlert,
        "Error alert should be visible in event details",
      ).toBeVisible();
    },
    errorAlertContainsText: async (text: string) => {
      await expect(locators.errorAlert, `Error alert should contain "${text}"`).toContainText(text);
    },
    accordionBodyIsVisible: async () => {
      await expect(
        locators.eventDetailsPanel.getByTestId("event-occurred-at"),
        "Accordion body content should be visible",
      ).toBeVisible();
    },
    accordionBodyIsHidden: async () => {
      await expect(
        locators.eventDetailsPanel.getByTestId("event-occurred-at"),
        "Accordion body content should be hidden",
      ).toBeHidden();
    },
  };
};
